export class ModalFamiliaCtrl{static get $inject(){return["$http","$uibModalInstance","formulario","params"]}constructor($http,$uibModalInstance,_form,_params){this.$http=$http,this.$uibModalInstance=$uibModalInstance,this._form=_form,this._params=_params,this.tipoRegistro=1,this.data={}}$onInit(){this._params&&(this.tipoRegistro=2,this.data=this._params)}getFamilyCode(){this._form.campo(this.data.descripcion)||1!==this.tipoRegistro||(this.data.siglas=this._form.obtenerTresLetras(this.data.descripcion))}saveAndUpdate(){const tituloToastr=1===this.tipoRegistro?"Nuevo":"Actualizar";if(this._form.campo(this.data.descripcion))return void toastr.warning("Por favor, ingrese la Descripción",tituloToastr);if(this._form.campo(this.data.siglas))return void toastr.warning("Por favor, ingrese la Sigla",tituloToastr);const url=1===this.tipoRegistro?"/Familia/Post":"/Familia/Put?idFamilia="+this.data.idFamilia;this.$http.post(url,this.data).then(({data:response})=>{if(console.log(response),"0"!==response.id&&"0"!==response.code)return"1"===response.id||"1"===response.code?(this.$uibModalInstance.close(response),void toastr.success(response.message,response.titleSms)):void 0;toastr.warning(response.message,response.titleSms)})}}